using System;using System.Drawing;using System.Linq;using System.Collections.Generic;
namespace Synkoz {public sealed partial class MontagePanel {
 void RefreshTrackThumbsR21(int track){if(Current==null)return;foreach(var file in Current.Blocks.Where(b=>b.Track==track).Select(ThumbFileA01).Where(x=>x!=null).Distinct().ToArray()){List<ThumbA01> images;if(thumbsA01.TryGetValue(file,out images)){thumbsA01.Remove(file);foreach(var item in images)item.Image.Dispose();}}LoadThumbsA01(true,track);}
 static void DrawOrientedThumbR21(Graphics g,Image source,Rectangle rect,Track track){using(var image=new Bitmap(source)){int angle=OrientationR2.Degrees(track);image.RotateFlip(angle==90?RotateFlipType.Rotate90FlipNone:angle==180?RotateFlipType.Rotate180FlipNone:angle==270?RotateFlipType.Rotate270FlipNone:RotateFlipType.RotateNoneFlipNone);if(track.Fx.MirrorX939)image.RotateFlip(RotateFlipType.RotateNoneFlipX);if(track.Fx.MirrorY939)image.RotateFlip(RotateFlipType.RotateNoneFlipY);double scale=Math.Min(rect.Width/(double)image.Width,rect.Height/(double)image.Height);g.DrawImage(image,new RectangleF(rect.X+(float)(rect.Width-image.Width*scale)/2,rect.Y+(float)(rect.Height-image.Height*scale)/2,(float)(image.Width*scale),(float)(image.Height*scale)));}}
 void DrawDbR21(Graphics g,Rectangle rect,int center,int height,AudioFxR2 fx){if(rect.Width<80||height<15)return;using(var font=new Font("Segoe UI",7)){foreach(int db in new[]{0,-6,-12,-24}){float y=center-(float)(Math.Pow(10,db/20.0)*height);g.DrawLine(Pens.DimGray,Math.Max(0,rect.Left),y,rect.Right,y);g.DrawString(db+" dBFS",font,Brushes.White,Math.Max(0,rect.Left)+3,y);}if(fx!=null&&fx.Enabled){if(fx.Compressor){float y=center-(float)(Math.Pow(10,fx.ThresholdDb/20)*height);g.DrawLine(Pens.Gold,rect.Left,y,rect.Right,y);}if(fx.Limiter){float y=center-(float)(Math.Pow(10,fx.LimitDb/20)*height);g.DrawLine(Pens.OrangeRed,rect.Left,y,rect.Right,y);}}}}
}}
